import {
  useCallback,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { AgentContext } from '../hooks/useAgent';
import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
import { useSessionId } from '../hooks/useSessionId';
import { generateUUID } from '../utils/uuid';

function generateId() {
  return generateUUID();
}

export function AgentProvider({
  children,
  refreshTables,
}: {
  children: ReactNode;
  refreshTables: () => Promise<void>;
}) {
  const userSessionId = useSessionId();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const textBufferRef = useRef('');
  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const assistantIdRef = useRef('');
  const segmentsRef = useRef<ContentSegment[]>([]);
  const currentTextRef = useRef('');
  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
  const sessionIdRef = useRef<string | null>(null);
  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);

  const flushText = useCallback(() => {
    const text = textBufferRef.current;
    if (!text) return;
    const id = assistantIdRef.current;
    currentTextRef.current += text;
    setMessages((prev) =>
      prev.map((m) =>
        m.id === id ? { ...m, content: m.content + text } : m
      )
    );
    textBufferRef.current = '';
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      if (isStreaming) return;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: text,
      };

      const assistantId = generateId();
      assistantIdRef.current = assistantId;
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev, userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';
      phaseRef.current = 'thinking';

      // Build conversation history from current messages for resume fallback
      const history = messages
        .filter((m) => m.role === 'user' || m.role === 'assistant')
        .map((m) => ({ role: m.role, content: m.content }));

      // If there's pending history from a delete, start a new Langfuse session with that context
      const pendingHistory = pendingHistoryRef.current;
      pendingHistoryRef.current = null;
      const langfuseSessionId = pendingHistory ? generateUUID() : null;

      const controller = new AbortController();
      abortRef.current = controller;

      await runAgentLoop(
        text,
        sessionIdRef.current,
        langfuseSessionId,
        pendingHistory ?? (history.length > 0 ? history : null),
        {
          onTextChunk: (chunk) => {
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            // Extended thinking just ended and a text block is starting.
            // Create a thinking segment from accumulated thinking text.
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            phaseRef.current = 'answer';
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            // Add a pending tool segment so the input is shown immediately
            segmentsRef.current.push({
              type: 'tool',
              toolResult: pending,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            // Merge result into pending tool segment (keep input info, add output)
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              sqlResults: data.sql_results,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({
                type: 'answer',
                text: currentTextRef.current,
              });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'error', errorMessage: error });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onUserQuestion: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'user_question',
              questionData: data,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
        },
        controller.signal,
        userSessionId,
      );
    },
    [isStreaming, flushText, refreshTables, userSessionId]
  );

  const editMessage = useCallback(
    async (messageIndex: number, newContent: string) => {
      if (isStreaming) return;

      // Build conversation history from messages before the edit point
      const conversationHistory: { role: string; content: string }[] = [];
      for (let i = 0; i < messageIndex; i++) {
        const msg = messages[i];
        if (msg.role === 'user' || msg.role === 'assistant') {
          conversationHistory.push({ role: msg.role, content: msg.content });
        }
      }

      const assistantId = generateId();
      assistantIdRef.current = assistantId;

      const userMsg: ChatMessage = {
        id: generateId(),
        role: 'user',
        content: newContent,
      };
      const assistantMsg: ChatMessage = {
        id: assistantId,
        role: 'assistant',
        content: '',
        toolCalls: [],
        isStreaming: true,
      };

      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
      setIsStreaming(true);
      textBufferRef.current = '';
      segmentsRef.current = [];
      currentTextRef.current = '';
      phaseRef.current = 'thinking';

      const controller = new AbortController();
      abortRef.current = controller;

      await runAgentEditLoop(
        newContent,
        conversationHistory,
        generateUUID(),
        {
          onTextChunk: (chunk) => {
            textBufferRef.current += chunk;
            if (!flushTimerRef.current) {
              flushTimerRef.current = setTimeout(() => {
                flushText();
                flushTimerRef.current = null;
              }, 50);
            }
          },
          onThinkingDone: () => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            phaseRef.current = 'answer';
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolCall: (pending: ToolCallResult) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'tool', toolResult: pending });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onToolResult: (result: ToolCallResult) => {
            const pendingIdx = segmentsRef.current.findIndex(
              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
            );
            if (pendingIdx !== -1) {
              const pending = segmentsRef.current[pendingIdx].toolResult!;
              segmentsRef.current[pendingIdx] = {
                type: 'tool',
                toolResult: {
                  ...pending,
                  ...result,
                  sql: result.sql || pending.sql,
                  toolName: result.toolName || pending.toolName,
                  command: result.command || pending.command,
                  toolInput: result.toolInput || pending.toolInput,
                },
              };
            } else {
              segmentsRef.current.push({ type: 'tool', toolResult: result });
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
                  : m
              )
            );
            refreshTables();
          },
          onSubagentStart: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'subagent_start',
              subagentId: data.id,
              subagentName: data.name,
              text: data.prompt,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onSubagentEnd: (data) => {
            segmentsRef.current.push({
              type: 'subagent_end',
              subagentId: data.id,
              subagentName: data.name,
              chart_spec: data.chart_spec,
              sqlResults: data.sql_results,
              text: data.result,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
          onDone: (newSessionId) => {
            if (newSessionId) sessionIdRef.current = newSessionId;
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
              currentTextRef.current = '';
            }
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onError: (error) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({ type: 'error', errorMessage: error });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
                  : m
              )
            );
            setIsStreaming(false);
            abortRef.current = null;
          },
          onUserQuestion: (data) => {
            if (flushTimerRef.current) {
              clearTimeout(flushTimerRef.current);
              flushTimerRef.current = null;
            }
            flushText();
            if (currentTextRef.current.trim()) {
              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
              currentTextRef.current = '';
            }
            segmentsRef.current.push({
              type: 'user_question',
              questionData: data,
            });
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantId
                  ? { ...m, segments: [...segmentsRef.current] }
                  : m
              )
            );
          },
        },
        controller.signal,
        userSessionId,
      );
    },
    [isStreaming, messages, flushText, refreshTables, userSessionId]
  );

  const deleteMessage = useCallback(
    (messageIndex: number) => {
      if (isStreaming) return;

      // Store remaining messages as history for Langfuse context on next send
      setMessages((prev) => {
        const remaining = prev.slice(0, messageIndex);
        pendingHistoryRef.current = remaining
          .filter((m) => m.role === 'user' || m.role === 'assistant')
          .map((m) => ({ role: m.role, content: m.content }));
        return remaining;
      });

      // Clear session so next message starts fresh
      sessionIdRef.current = null;
    },
    [isStreaming]
  );

  const respondToQuestion = useCallback(
    async (questionId: string, answers: string[], freeText?: string) => {
      // Update the segment to show the user's answer
      const segIdx = segmentsRef.current.findIndex(
        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
      );
      if (segIdx !== -1) {
        segmentsRef.current[segIdx] = {
          ...segmentsRef.current[segIdx],
          userAnswer: answers,
          userFreeText: freeText,
        };
        setMessages((prev) =>
          prev.map((m) =>
            m.id === assistantIdRef.current
              ? { ...m, segments: [...segmentsRef.current] }
              : m
          )
        );
      }

      // POST to backend
      try {
        await fetch('/api/chat/respond', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
          },
          body: JSON.stringify({
            question_id: questionId,
            answers,
            free_text: freeText || null,
          }),
        });
      } catch (e) {
        console.error('Failed to respond to question:', e);
      }
    },
    [userSessionId]
  );

  const clearMessages = useCallback(() => {
    if (abortRef.current) {
      abortRef.current.abort();
    }
    setMessages([]);
    setIsStreaming(false);
    sessionIdRef.current = null;
    pendingHistoryRef.current = null;
  }, []);

  return (
    <AgentContext.Provider
      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
    >
      {children}
    </AgentContext.Provider>
  );
}

import { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { useTranslation } from '../hooks/useTranslation';
import type { ChatMessage, ContentSegment } from '../types';
import { useAgent } from '../hooks/useAgent';
import { InlineQueryResult } from './InlineQueryResult';
import { ChartWidget } from './ChartWidget';
import { UserQuestion } from './UserQuestion';
import './MessageBubble.css';

/**
 * Strip chart_spec JSON code blocks from answer text.
 * The orchestrator may include the raw chart spec JSON even though the chart
 * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 * or Plotly trace data so they don't appear as raw text.
 */
function stripChartSpecBlocks(text: string): string {
  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
}

/**
 * Fix missing line breaks before bold section headers in thinking text.
 * The model sometimes concatenates bold headers directly after the previous
 * sentence (e.g. "...for arrays.**Preparing data arrays**"). This inserts
 * paragraph breaks so they render on new lines.
 */
function fixThinkingLineBreaks(text: string): string {
  // Insert \n\n before **Header** when preceded by sentence-ending punctuation
  // with no whitespace. The [A-Z] ensures we only match section-header-style
  // bold (starting with a capital letter), avoiding inline bold like **data**.
  return text.replace(/([.!?:])(\*\*[A-Z])/g, '$1\n\n$2');
}

/** Strip markdown formatting for plain-text preview display. */
function stripMarkdown(text: string): string {
  return text
    .replace(/\*\*(.+?)\*\*/g, '$1')   // **bold**
    .replace(/__(.+?)__/g, '$1')        // __bold__
    .replace(/\*(.+?)\*/g, '$1')        // *italic*
    .replace(/_(.+?)_/g, '$1')          // _italic_
    .replace(/`(.+?)`/g, '$1')          // `code`
    .replace(/^#+\s+/gm, '');           // # headings
}

function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
  // Use streaming remainder if available
  if (streamingRemainder?.trim()) {
    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
    const last = stripMarkdown(lines[lines.length - 1] || '');
    return last.length > 100 ? last.slice(0, 100) + '...' : last;
  }
  // Otherwise use last thinking segment's last line
  for (let i = segments.length - 1; i >= 0; i--) {
    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
      const last = stripMarkdown(lines[lines.length - 1] || '');
      return last.length > 100 ? last.slice(0, 100) + '...' : last;
    }
  }
  return t('thinking');
}

function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
  segments: ContentSegment[];
  streamingRemainder?: string;
  isThinkingPhase: boolean;
  isAgentStreaming: boolean;
  hasAnswer: boolean;
}) {
  const { t } = useTranslation();
  // All non-answer, non-chart, non-user_question segments go inside the thinking block.
  // subagent_end with sqlResults always stays in thinking; text-only subagent_end without
  // answer goes to the answer block as a preliminary result.
  const thinkingSegments = segments.filter(
    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (!s.sqlResults?.length && s.text?.trim() && !hasAnswer)))
  );
  const hasContent = thinkingSegments.some(
    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && (s.text?.trim() || s.sqlResults?.length))
  ) || streamingRemainder?.trim();

  if (!hasContent) return null;

  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';

  return (
    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || undefined}>
      <summary className="message-bubble__collapsible-summary">
        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
      </summary>
      <div className="message-bubble__thinking-body">
        {thinkingSegments.map((seg, i) => {
          if (seg.type === 'thinking' && seg.text?.trim()) {
            return (
              <div key={i} className="message-bubble__segment-content">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixThinkingLineBreaks(seg.text)}</ReactMarkdown>
              </div>
            );
          }
          if (seg.type === 'tool' && seg.toolResult) {
            return (
              <div key={i} className="message-bubble__tool-segment">
                <InlineQueryResult result={seg.toolResult} />
              </div>
            );
          }
          if (seg.type === 'subagent_start') {
            const displayName = seg.subagentName === 'sql-analyst'
              ? t('sqlAnalystWorking')
              : `${seg.subagentName} working...`;
            return (
              <div key={i} className="message-bubble__subagent-indicator">
                <span className="message-bubble__subagent-label">{displayName}</span>
              </div>
            );
          }
          if (seg.type === 'subagent_end' && !seg.chart_spec && (seg.sqlResults?.length || seg.text?.trim())) {
            // Render SQL results using InlineQueryResult — same as direct tool calls
            if (seg.sqlResults?.length) {
              return (
                <div key={i}>
                  {seg.sqlResults.map((sqlResult, qi) => (
                    <div key={qi} className="message-bubble__tool-segment">
                      <InlineQueryResult result={{
                        toolCallId: `${seg.subagentId}-sql-${qi}`,
                        toolName: 'execute_sql',
                        sql: sqlResult.sql,
                        columns: sqlResult.columns ?? [],
                        rows: sqlResult.rows ?? [],
                        rowCount: sqlResult.rowCount ?? 0,
                        error: sqlResult.error,
                      }} />
                    </div>
                  ))}
                </div>
              );
            }
            return (
              <div key={i} className="message-bubble__segment-content">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
              </div>
            );
          }
          return null;
        })}
        {streamingRemainder?.trim() && (
          <div className="message-bubble__segment-content">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixThinkingLineBreaks(streamingRemainder)}</ReactMarkdown>
          </div>
        )}
      </div>
    </details>
  );
}

function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
  const { t } = useTranslation();
  return (
    <div className="message-bubble__segment message-bubble__segment--error">
      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
      <div className="message-bubble__error-message">{errorMessage}</div>
      {onRetry && (
        <button className="message-bubble__error-retry" onClick={onRetry}>
          {t('tryAgain')}
        </button>
      )}
    </div>
  );
}

export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
  const { t } = useTranslation();
  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(message.content);
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const isUser = message.role === 'user';
  const hasSegments = !isUser && message.segments && message.segments.length > 0;

  useEffect(() => {
    if (isEditing && textareaRef.current) {
      textareaRef.current.focus();
      textareaRef.current.selectionStart = textareaRef.current.value.length;
    }
  }, [isEditing]);

  const handleEdit = () => {
    setEditText(message.content);
    setIsEditing(true);
    setIsConfirmingDelete(false);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditText(message.content);
  };

  const handleSaveEdit = () => {
    const trimmed = editText.trim();
    if (!trimmed || trimmed === message.content) {
      handleCancelEdit();
      return;
    }
    setIsEditing(false);
    editMessage(messageIndex, trimmed);
  };

  const handleDeleteConfirm = () => {
    setIsConfirmingDelete(false);
    deleteMessage(messageIndex);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      handleCancelEdit();
    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      handleSaveEdit();
    }
  };

  // Compute streamingRemainder for all streaming assistant messages, not just
  // those with segments.  Before any segments exist (i.e. during the thinking
  // phase before thinking_done fires), the entire m.content IS the remainder
  // and should render inside the ThinkingBlock, not as plain content.
  let streamingRemainder: string | undefined;
  if (!isUser && message.isStreaming && message.content) {
    const segments = message.segments ?? [];
    const segmentedText = segments
      .filter((s) => s.type === 'thinking' || s.type === 'answer')
      .map((s) => s.text || '')
      .join('');
    const remaining = message.content.slice(segmentedText.length);
    if (remaining.trim()) {
      streamingRemainder = remaining;
    }
  }

  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
  const isInAnswerPhase = message.currentPhase === 'answer';
  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;

  const hasCharts = hasSegments && message.segments!.some(
    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
  );

  const answerBlockSegments = hasSegments
    ? message.segments!
        .filter((s) =>
          (s.type === 'answer' && s.text?.trim()) ||
          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
          (s.type === 'tool' && s.toolResult?.chart_spec) ||
          (s.type === 'subagent_end' && s.chart_spec)
        )
        .map((s) => {
          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
            return { ...s, text: stripChartSpecBlocks(s.text) };
          }
          return s;
        })
        .filter((s) => {
          // Remove text segments that became empty after stripping chart blocks
          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
            return false;
          }
          return true;
        })
    : [];

  const questionSegments = hasSegments
    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
    : [];

  return (
    <div className={`message-bubble message-bubble--${message.role}`}>
      <div className="message-bubble__header">
        {isUser ? t('you') : t('assistant')}
        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
          <span className="message-bubble__actions">
            <button
              className="message-bubble__action-btn"
              onClick={handleEdit}
              title={t('editMessage')}
            >
              &#9998;
            </button>
            <button
              className="message-bubble__action-btn message-bubble__action-btn--delete"
              onClick={() => setIsConfirmingDelete(true)}
              title={t('deleteMessage')}
            >
              &#128465;
            </button>
          </span>
        )}
      </div>

      {isUser && isConfirmingDelete && (
        <div className="message-bubble__confirm-delete">
          <span>{t('deleteConfirm')}</span>
          <div className="message-bubble__confirm-actions">
            <button
              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
              onClick={handleDeleteConfirm}
            >
              {t('delete')}
            </button>
            <button
              className="message-bubble__confirm-btn"
              onClick={() => setIsConfirmingDelete(false)}
            >
              {t('cancel')}
            </button>
          </div>
        </div>
      )}

      {isUser && isEditing ? (
        <div className="message-bubble__edit-mode">
          <textarea
            ref={textareaRef}
            className="message-bubble__edit-textarea"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onKeyDown={handleKeyDown}
            rows={3}
          />
          <div className="message-bubble__edit-actions">
            <button
              className="message-bubble__edit-btn message-bubble__edit-btn--save"
              onClick={handleSaveEdit}
            >
              {t('saveResend')}
            </button>
            <button
              className="message-bubble__edit-btn"
              onClick={handleCancelEdit}
            >
              {t('cancel')}
            </button>
          </div>
        </div>
      ) : (hasSegments || (!!message.isStreaming && !isUser)) ? (
        <div className="message-bubble__segments">
          {!questionSegments.some((s) => !s.userAnswer) && (
            <ThinkingBlock
              segments={message.segments ?? []}
              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
              isThinkingPhase={isThinkingPhase}
              isAgentStreaming={!!message.isStreaming}
              hasAnswer={hasAnswer}
            />
          )}
          {questionSegments.map((seg, i) => (
            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
              <UserQuestion
                questionData={seg.questionData!}
                userAnswer={seg.userAnswer}
                userFreeText={seg.userFreeText}
              />
            </div>
          ))}
          {answerBlockSegments.length > 0 && (
            <div className="message-bubble__segment message-bubble__segment--answer">
              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
              {answerBlockSegments.map((seg, i) => {
                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
                  return (
                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
                      {seg.type === 'tool' && seg.toolResult ? (
                        <InlineQueryResult result={seg.toolResult!} />
                      ) : seg.chart_spec ? (
                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
                      ) : null}
                    </div>
                  );
                }
                // Text segment (answer or subagent_end without chart_spec)
                return (
                  <div key={`answer-${i}`} className="message-bubble__segment-content">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
                  </div>
                );
              })}
              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
                return displayText?.trim() ? (
                  <div className="message-bubble__segment-content">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
                  </div>
                ) : null;
              })()}
            </div>
          )}
          {/* Only show standalone streaming answer block when no answer segments exist yet */}
          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
            return displayText?.trim() ? (
              <div className="message-bubble__segment message-bubble__segment--answer">
                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
                <div className="message-bubble__segment-content">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
                </div>
              </div>
            ) : null;
          })()}
          {(message.segments ?? []).filter((s) => s.type === 'error').map((seg, i) => {
            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
          })}
          {message.isStreaming && !message.content && questionSegments.length === 0 && (
            <span className="message-bubble__typing">{t('thinking')}</span>
          )}
        </div>
      ) : (
        <>
          <div className="message-bubble__content">
            {message.content ? (
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
            ) : message.isStreaming ? (
              <span className="message-bubble__typing">{t('thinking')}</span>
            ) : null}
          </div>
          {message.toolCalls && message.toolCalls.length > 0 && (
            <div className="message-bubble__tools">
              {message.toolCalls.map((tc) => (
                <InlineQueryResult key={tc.toolCallId} result={tc} />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

